16	// 本文件钉住 README“稳定编码规则”下的确切字节，而不仅是两次运行相等：
17	// 字段次序、固定前缀及其末尾换行、Base64 填充、uint64 十进制表示或
18	// 签名字段位置中的任何一项发生偏离，即使本地签名与验签同时采用变化后的
19	// 表示，这些预期常量也会失配并指出与公开约定不一致。
20	
21	// stableSigningPrefix 是公开签名编码的固定前缀（含末尾换行）。
22	const stableSigningPrefix = "consensus-lab-tx-v1\n"
23	
24	// stableSenderB64 是回归向量使用的发送者公钥：
25	// 由确定性种子 0x01,0x02,...,0x20 派生的 Ed25519 公钥，任何人都可重建。
26	const stableSenderB64 = "ebVWLo/mVPlAeLES6KmLp5AfhTrmlb7X4OORC60ElmQ="
27	
28	func stablePrivateKey(t *testing.T) ed25519.PrivateKey {
29		t.Helper()
30		seed := make([]byte, ed25519.SeedSize)
31		for i := range seed {
32			seed[i] = byte(i + 1)
33		}
34		return ed25519.NewKeyFromSeed(seed)
35	}
36	
37	// encVector 的每个预期值都可依据 README 的公开规则独立核对：
38	// canonicalDoc 按字段名手工拼接，签名是标准 Ed25519 对“前缀+文档”的签名，
39	// 标识是含签名字段文档的 SHA-256 十六进制摘要。
40	type encVector struct {
41		name         string
42		sequence     uint64
43		content      []byte
44		contentB64   string
45		fee          uint64
46		expiry       uint64
47		signatureB64 string
48		id           string
49	}
